<?php
require_once __DIR__.'/../../app/config/init.php';require_login();require_role('Administrator','Supply Officer','Property Officer');require_once __DIR__.'/dtr_helpers.php';$db=db();$schedule=$db?dtr_load_schedule($db):dtr_default_schedule();$traineeId=(int)($_GET['trainee_id']??0);$month=trim($_GET['month']??'');$trainees=[];$trainee=null;$logs=[];$scoped=$traineeId>0&&preg_match('/^\d{4}-\d{2}$/',$month);
if($db){$res=$db->query('SELECT id,first_name,middle_name,last_name FROM dtr_trainees WHERE is_active=1 ORDER BY last_name,first_name');if($res)$trainees=$res->fetch_all(MYSQLI_ASSOC);if($scoped){$stmt=$db->prepare('SELECT * FROM dtr_trainees WHERE id=?');$stmt->bind_param('i',$traineeId);$stmt->execute();$trainee=$stmt->get_result()->fetch_assoc();$stmt->close();$start=$month.'-01';$end=date('Y-m-t',strtotime($start));$stmt=$db->prepare("SELECT DATE(logged_at) d,MIN(CASE WHEN log_type='time_in' THEN logged_at END) time_in,MAX(CASE WHEN log_type='time_out' THEN logged_at END) time_out FROM dtr_logs WHERE trainee_id=? AND DATE(logged_at) BETWEEN ? AND ? GROUP BY DATE(logged_at)");$stmt->bind_param('iss',$traineeId,$start,$end);$stmt->execute();foreach($stmt->get_result() as $row)$logs[$row['d']]=$row;$stmt->close();}}
?><!doctype html><html><head><meta charset="utf-8"><title>Daily Time Record</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"><style>@page{size:legal portrait;margin:.35in}body{color:#000}.form{max-width:760px;margin:auto;border:1px solid #000;padding:18px}.dtr{width:100%;border-collapse:collapse}.dtr th,.dtr td{border:1px solid #000;padding:4px;text-align:center;font-size:12px;height:25px}.dtr th{font-weight:700}.cert{font-size:12px;margin-top:28px}.line{border-bottom:1px solid #000;display:inline-block;min-width:260px}@media print{.no-print{display:none!important}.form{border:0}}</style></head><body><div class="container my-3"><div class="no-print card mb-3"><div class="card-body"><form class="row g-2"><div class="col-md-6"><select class="form-select" name="trainee_id" required><option value="">Select trainee</option><?php foreach($trainees as $t):?><option value="<?php echo(int)$t['id'];?>" <?php echo $traineeId===(int)$t['id']?'selected':'';?>><?php echo h(trim($t['last_name'].', '.$t['first_name'].' '.$t['middle_name']));?></option><?php endforeach;?></select></div><div class="col-md-4"><input class="form-control" type="month" name="month" required value="<?php echo h($month);?>"></div><div class="col-md-2"><button class="btn btn-primary">Load DTR</button></div></form><?php if($scoped&&$trainee):?><button class="btn btn-outline-primary mt-2" onclick="window.print()">Print</button><?php endif;?></div></div><?php if(!$scoped):?><div class="text-center text-muted py-5">Choose a trainee and month to generate the Daily Time Record.</div><?php elseif(!$trainee):?><div class="alert alert-info">Trainee not found.</div><?php else:$start=strtotime($month.'-01');$days=(int)date('t',$start);?><div class="form"><div class="text-end small">Civil Service Form No. 48</div><div class="text-center"><strong>DAILY TIME RECORD</strong><div>For the month of <?php echo h(date('F Y',$start));?></div></div><div class="mt-3">Name: <span class="line"><?php echo h(trim($trainee['first_name'].' '.$trainee['middle_name'].' '.$trainee['last_name']));?></span></div><div class="small text-muted">OJT Trainee · Course: <?php echo h($trainee['course']??'');?> · Year Level: <?php echo h($trainee['year_level']??'');?></div><div class="mt-2 small">Official hours for arrival and departure</div><table class="dtr"><thead><tr><th rowspan="2">Day</th><th colspan="2">A.M.</th><th colspan="2">P.M.</th><th colspan="2">Undertime</th></tr><tr><th>Arrival</th><th>Departure</th><th>Arrival</th><th>Departure</th><th>Hours</th><th>Minutes</th></tr></thead><tbody><?php for($d=1;$d<=$days;$d++):$date=$month.'-'.str_pad((string)$d,2,'0',STR_PAD_LEFT);$l=$logs[$date]??[];$in=$l['time_in']??null;$out=$l['time_out']??null;?><tr><td><?php echo $d;?></td><td><?php echo $in?h(date('g:i A',strtotime($in))):'';?></td><td></td><td></td><td><?php echo $out?h(date('g:i A',strtotime($out))):'';?></td><td></td><td></td></tr><?php endfor;?></tbody></table><div class="cert">I CERTIFY on my honor that the above is a true and correct report of the hours of work performed, record of which was made daily at the time of arrival at and departure from office.<br><br><div class="text-center"><span class="line"></span><br>Signature</div><br>Verified as to the prescribed office hours: <span class="line"></span><br><div class="text-center">In Charge</div></div></div><?php endif;?></div></body></html>
